Definition sd_segD_post (sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fb : fbv) (m : mem) : machine_state -> Prop :=
  fun ms' =>
    ms' = MS (mkR (Z_to_bv 64 P_SD_MID) sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (fb_begin Fb)) (Z_to_bv 64 (fb_cap Fb)) a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPDEL2) fc None m (seg_rom rsegs)
    /\ munch [] m m /\ wmono rsegs m m /\ mem_inv rsegs m.

