    (F : bvmap 5 word) fc (m : mem) (stb : Z) (Fb : fbv),
  ro_cells rsegs m (stb + 144) (FlatBufCells Fb) -> 0 < fb_begin Fb -> fb_begin Fb <= fb_end Fb -> fb_end Fb <= hceil ->
  0 < stb -> stb + 312 <= hceil ->
  mem_inv rsegs m ->
  evt rsegs (sd_segD_post sp gp tp t0 t1 t2 (Z_to_bv 64 (stb + 32)) s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc Fb m)
    (MS (mkR ra sp gp tp t0 t1 t2 (Z_to_bv 64 (stb + 32)) s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
