(* [comment removed for export] *)
Definition sd_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (stb implb u ii lk lo : Z) (ij7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (implb + 12, implb + 16)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ PMutex m' (stb + 104) lk
    /\ rw_cells rsegs m' implb (SpcHdrCells (mkSPC VP_SPCI_IMPL u 1 ii) ij7).

Lemma sd_segB : forall (rax : word) sp gp tp t0 t1 t2 (s1x s2x : word) a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (ra s0 s1 s2 : word) (F : bvmap 5 word) fc (m : mem) (stb implb ioc u ii lk lo : Z) (junk ij7 j16 : list byte),
  rw_cells rsegs m (bv_unsigned sp + -64) [CB 32 junk; C8 s2; C8 s1; C8 s0; C8 ra] ->
  PMutex m (stb + 104) lk ->
  ro_cells rsegs m (stb + 88) [C8 (wz (implb + 32)); C8 (wz implb)] ->
  ro_cells rsegs m (stb + 32) (AnyExecCells (stb + 32) ioc j16) ->
  rw_cells rsegs m implb (SpcHdrCells (mkSPC VP_SPCI_IMPL u 2 ii) ij7) -> 0 <= u < 2^31 -> (ii = 0 \/ ii = 1) ->
  XStatics m ->
  0 < stb -> stb + 312 <= hceil -> 0 < implb -> implb mod 16 = 0 -> implb + 96 <= hceil ->
  (stb + 312 <= implb \/ implb + 96 <= stb) -> (implb + 96 <= 0x10000 \/ 0xb4000 <= implb) ->
  stk rsegs m lo (bv_unsigned sp + -64) -> lo + 80 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (sd_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc stb implb u ii lk lo ij7 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (Z_to_bv 64 (stb + 32)) s1x a0 a1 a2 a3 a4 a5 a6 a7
             s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SD_MID) fc None m (seg_rom rsegs)).
