(* [comment removed for export] *)
(* [comment removed for export] *)

Definition STATE_DTOR_STACK : Z := 64 + RFREE_STACK.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition fb_off (Fb : fbv) (a n : Z) : Prop := fb_end Fb <= a \/ a + n <= fb_begin Fb.

(* [comment removed for export] *)
Definition sd_X (implb : Z) (Fb : fbv) : list (Z * Z) :=
  (implb + 12, implb + 16) :: (if fb_begin Fb =? 0 then [] else [(fb_begin Fb, fb_end Fb)]).

(* [comment removed for export] *)
Definition impl_weak (I : implv) (w : Z) : implv :=
  mkIMPL (mkSPC (spc_vptr (im_hdr I)) (spc_use (im_hdr I)) w (spc_init (im_hdr I))) (im_lk I) (im_vb I) (im_states I) (im_vcap I).

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  (* [comment removed for export] *)
  Definition sd_LB (Fb : fbv) (pf : bptr) (LB : list block) : list block :=
    if fb_begin Fb =? 0 then LB else hs_lb_remove H pf LB.

  Definition state_dtor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (stb implb lo B : Z) (S : statev) (I : implv) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (pf p : bptr) (j7 : list byte),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ (st_fb S <> FB_empty -> In (pf, fb_begin (st_fb S), fb_cap (st_fb S)) LB)
      /\ hs_RHEAP H s' (sd_LB (st_fb S) pf LB) m'
      /\ In (p, stb, SZ_SPCI_STATE) (sd_LB (st_fb S) pf LB)
      /\ rw_cells rsegs m' stb (SpcHdrCells (st_hdr S) j7)
      /\ ImplBlock (sd_LB (st_fb S) pf LB) m' implb (impl_weak I 1)
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) (sd_X implb (st_fb S)) m m'.

  Definition state_dtor_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (stb ioc implb lo B : Z) (S : statev) (ds : list byte) (I : implv) (errv : word),
      a0 = Z_to_bv 64 (stb + 32) ->
      (* [comment removed for export] *)
